package main

import "fmt"

// generate returns a receive-only channel: callers can only read from it.
func generate(n int) <-chan int {
	out := make(chan int) // bidirectional, owned here
	go produce(out, n)    // 'out' converts to chan<- int for produce
	return out            // returned as <-chan int
}

// produce takes a send-only channel: it may only send and close.
func produce(out chan<- int, n int) {
	for i := 1; i <= n; i++ {
		out <- i // allowed: send-only permits sending
	}
	close(out)   // the producer owns closing
	// <-out      // COMPILE ERROR: receive from send-only channel
}

// consume takes a receive-only channel: it may only receive.
func consume(in <-chan int) int {
	sum := 0
	for v := range in { // ranges until the channel is closed
		sum += v
	}
	// in <- 0          // COMPILE ERROR: send to receive-only channel
	// close(in)        // COMPILE ERROR: cannot close receive-only channel
	return sum
}

func main() {
	nums := generate(5) // nums has type <-chan int
	fmt.Println("sum:", consume(nums))
}

package main

import (
	"fmt"
	"sync"
	"time"
)

func main() {
	const maxConcurrent = 2
	sem := make(chan struct{}, maxConcurrent) // capacity = concurrency limit

	var wg sync.WaitGroup
	for task := 1; task <= 5; task++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			sem <- struct{}{}        // acquire: blocks if N are already running
			defer func() { <-sem }() // release a slot on exit

			fmt.Printf("task %d running (in-flight=%d)\n", id, len(sem))
			time.Sleep(10 * time.Millisecond) // simulate work
		}(task)
	}
	wg.Wait()
	fmt.Println("all tasks done")
}
